import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"网络问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/network-issues.md","filePath":"zh/troubleshooting/network-issues.md"}'),o={name:"zh/troubleshooting/network-issues.md"};function l(i,e,p,r,c,d){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="网络问题排查" tabindex="-1">网络问题排查 <a class="header-anchor" href="#网络问题排查" aria-label="Permalink to &quot;网络问题排查&quot;">​</a></h1><h2 id="有序排查" tabindex="-1">有序排查 <a class="header-anchor" href="#有序排查" aria-label="Permalink to &quot;有序排查&quot;">​</a></h2><p>运行 <code>net-tool</code> 走一遍菜单，或使用经典拼写：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; hwinfo                 (wizard: PCI page - is the NIC on the bus?)</span></span>
<span class="line"><span>ush&gt; ip                     (address bound? 0.0.0.0 = none)</span></span>
<span class="line"><span>ush&gt; dhcp                   (address + gateway + DNS in one shot)</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2          (ICMP to the QEMU gateway)</span></span>
<span class="line"><span>ush&gt; arp                    (L2 resolution happened?)</span></span>
<span class="line"><span>ush&gt; dns example.com        (UDP + resolver OK?)</span></span>
<span class="line"><span>ush&gt; wget example.com 80 /  (full TCP + HTTP round trip)</span></span>
<span class="line"><span>ush&gt; tcpstats               (per-connection counters)</span></span></code></pre></div><p>每一步隔离一层：总线 -&gt; 驱动 -&gt; L2 -&gt; L3 -&gt; L4 -&gt; 应用。<code>update</code> 向导在真正检查更新之前，跑的正是这条阶梯的 前几步（IP -&gt; DHCP 修复 -&gt; DNS）。</p><h2 id="qemu-细节" tabindex="-1">QEMU 细节 <a class="header-anchor" href="#qemu-细节" aria-label="Permalink to &quot;QEMU 细节&quot;">​</a></h2><ul><li>用户态网络永远提供 10.0.2.2（网关）和 DNS 转发——无需 宿主机配置。</li><li>默认的 <code>-device e1000</code> 是测试最充分的路径。</li><li>双实例测试：共享的 <code>-netdev socket/multicast</code> 为网卡测试 提供一条真实的双节点链路。</li><li><strong>首次连接 sshd 停摆</strong>：DHCP 之后 ARP 缓存是冷的——先跑 一个客户端方向的命令（<code>ping</code> 对端）把它暖起来。</li></ul><h2 id="tls-ssh-细节" tabindex="-1">TLS/SSH 细节 <a class="header-anchor" href="#tls-ssh-细节" aria-label="Permalink to &quot;TLS/SSH 细节&quot;">​</a></h2><ul><li>证书失败会打印确切的验证阶段（链/主机名/策略）——读那条 消息；信任模型（无锚点告警、命名主机失配致命）见 <a href="./../arch/network-stack.html">arch/network-stack.md</a>。</li><li>sshd 主机密钥：首次启动时生成，或预先在 /etc 卷上播种 <code>ssh_host_key</code>（<code>tools/host_keygen_etc.py</code>， 或 <a href="./../dev/e2e-suites.html">../dev/e2e-suites.md</a> 中的 mtools 配方）——这是 E2E 套件的前置条件。</li></ul>`,9)])])}const g=s(o,[["render",l]]);export{u as __pageData,g as default};
